import {
  REPORT_LEVELS,
  type ValidationReport,
} from 'src/types/validationReport';
import type { Translate } from 'src/utils/translate';
import { formatReportCounts } from './reportCounts';

// Date-only invoice values must not shift to the previous day in western zones.
export function formatReportDate(
  value: string | undefined,
  locale = 'en',
  time = false,
) {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return new Intl.DateTimeFormat(locale, {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    ...(time
      ? ({ hour: '2-digit', minute: '2-digit', second: '2-digit' } as const)
      : { timeZone: 'UTC' }),
  }).format(date);
}

export const severity = (value: string) =>
  value === 'fatal' ? 'error' : value;
export function reportView(
  report: ValidationReport,
  t: Translate,
  te = (key: string) => {
    const value = t(key);
    return Boolean(value && value !== key);
  },
  locale = 'en',
) {
  const label = (key: string) => t(`einvoice_report_${key}`);
  const findings = (report.findings || []).map((f) => {
    const key = `einvoice_finding_${f.code.replace(/-/g, '_')}`;
    const plainText = te(`${key}_text`) ? t(`${key}_text`) : undefined;
    return {
      ...f,
      plainText,
      message: plainText ?? f.message,
      technicalMessage:
        plainText !== undefined && f.message?.trim() && f.message !== plainText
          ? f.message
          : '',
      fix: te(`${key}_fix`) ? t(`${key}_fix`) : '',
      ruleSeverity: severity(f.original_severity || f.severity),
      effectiveSeverity: severity(f.severity),
      overridden: Boolean(
        f.original_severity && f.original_severity !== f.severity,
      ),
    };
  });
  const counts = findings.reduce(
    (c, f) => {
      c[
        f.effectiveSeverity === 'error'
          ? 'errors'
          : f.effectiveSeverity === 'warning'
            ? 'warnings'
            : 'info'
      ]++;
      return c;
    },
    { errors: 0, warnings: 0, info: 0 },
  );
  const formattedCounts = formatReportCounts(t, locale, counts);
  const assessment =
    report.assessment ||
    (!report.is_valid
      ? 'not_valid'
      : counts.warnings
        ? 'valid_with_warnings'
        : 'valid');
  const metadata = [
    ['reference', report.file_name],
    ['checked_at', formatReportDate(report.checked_at, locale, true)],
    [
      'document_type',
      [report.xrechnung_type, report.syntax, report.profile, report.version]
        .filter(Boolean)
        .join(' · '),
    ],
    ['rule_sets', report.bundle_version],
    ['seller', report.seller_name],
    [
      'number_date',
      [report.invoice_number, formatReportDate(report.invoice_date, locale)]
        .filter(Boolean)
        .join(' / '),
    ],
  ]
    .filter(([, value]) => value)
    .map(([key, value]) => ({ key: key!, label: label(key!), value: value! }));
  const levels = REPORT_LEVELS.filter((key) => report.level_summary?.[key]).map(
    (key) => ({ key, label: label(key), ...report.level_summary![key]! }),
  );
  return {
    metadata,
    findings,
    levels,
    counts,
    assessment,
    verdict: label(assessment),
    countText: t('einvoice_report_counts', formattedCounts),
    organisationCountText: t(
      'einvoice_report_organisation_counts',
      formattedCounts,
    ),
    assessmentText: report.assessment
      ? report.assessment_text_key && te(report.assessment_text_key)
        ? t(report.assessment_text_key)
        : label(`assessment_${report.assessment}`)
      : '',
  };
}

export function escapeMarkup(value: unknown): string {
  return String(value ?? '')
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\ufffe\uffff]/g, '')
    .replace(
      /[&<>"']/g,
      (c) =>
        ({
          '&': '&amp;',
          '<': '&lt;',
          '>': '&gt;',
          '"': '&quot;',
          "'": '&apos;',
        })[c]!,
    );
}
export function generateReportHtml(
  report: ValidationReport,
  t: Translate,
  locale = 'en',
): string {
  const v = reportView(report, t, undefined, locale),
    e = escapeMarkup;
  const l = (key: string) => e(t(`einvoice_report_${key}`));
  const table = (headers: string[], rows: string[][]) =>
    `<table><thead><tr>${headers.map((h) => `<th>${l(h)}</th>`).join('')}</tr></thead><tbody>${rows.map((row) => `<tr>${row.map((cell) => `<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
  const levels = v.levels.length
    ? v.levels
    : Object.entries(report.summary || {}).map(([key, c]) => ({
        ...c,
        label: t(`einvoice_report_${key}`),
      }));
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${l('title')}</title><style>body{font:14px system-ui;color:#263238;max-width:1100px;margin:24px auto;padding:20px}dl{display:grid;grid-template-columns:180px 1fr;gap:8px}dd{margin:0}table{border-collapse:collapse;width:100%;margin:12px 0}th,td{padding:8px;border-bottom:1px solid #ddd;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#f6f8fa}aside{padding:12px;border:1px solid #8899aa;background:#f6f8fa}code{overflow-wrap:anywhere}h1{font-size:22px}h2{font-size:18px}.technical-message{display:block;font-size:12px;margin-top:4px}</style></head><body><h1>${l('title')}</h1><dl>${v.metadata.map((m) => `<dt>${e(m.label)}</dt><dd>${e(m.value)}</dd>`).join('')}</dl><aside><strong>${e(v.verdict)}</strong> ${e(v.countText)} ${e(v.organisationCountText)}</aside><h2>${l('levels')}</h2>${table(
    ['levels', 'errors', 'warnings', 'info'],
    levels.map((r) => [e(r.label), e(r.errors), e(r.warnings), e(r.info)]),
  )}<h2>${l('findings')}</h2>${table(
    ['position', 'code', 'level', 'organisation', 'field_text'],
    v.findings.map((f) => [
      e(f.position),
      e(f.code),
      l(f.ruleSeverity),
      f.overridden ? l(f.effectiveSeverity) : '–',
      `<strong>${e([f.field, f.field_name].filter(Boolean).join(' '))}</strong> ${e(f.message)}${f.technicalMessage ? `<small class="technical-message">${l('technical_message')}: ${e(f.technicalMessage)}</small>` : ''}${f.fix ? `<p>${l('fix')}: ${e(f.fix)}</p>` : ''}${f.value != null ? `<p>${l('value')}: ${e(f.value)}</p>` : ''}${f.xpath ? `<p><code>${e(f.xpath)}</code></p>` : ''}${f.line ? `<p>${l('line')} ${e(f.line)}${f.column ? `:${e(f.column)}` : ''}</p>` : ''}`,
    ]),
  )}${v.assessmentText ? `<aside><strong>${l('assessment')}:</strong> ${e(v.assessmentText)}</aside>` : ''}</body></html>`;
}
export function generateReportXml(
  report: ValidationReport,
  t?: Translate,
): string {
  const translatedFindings = t ? reportView(report, t).findings : undefined;
  const exportReport = translatedFindings
    ? {
        ...report,
        findings: report.findings.map((finding, index) => ({
          ...finding,
          ...(translatedFindings[index].plainText !== undefined
            ? { plain_text: translatedFindings[index].plainText }
            : {}),
        })),
      }
    : report;
  // Fixed element names; report keys are escaped attributes, never markup.
  const node = (key: string, value: unknown): string =>
    value == null
      ? ''
      : Array.isArray(value)
        ? `<entry name="${escapeMarkup(key)}">${value.map((v) => node('finding', v)).join('')}</entry>`
        : typeof value === 'object'
          ? `<entry name="${escapeMarkup(key)}">${Object.entries(value)
              .map(([k, v]) => node(k, v))
              .join('')}</entry>`
          : `<entry name="${escapeMarkup(key)}">${escapeMarkup(value)}</entry>`;
  return `<?xml version="1.0" encoding="UTF-8"?><validation-report template="DocBits">${Object.entries(
    exportReport,
  )
    .map(([k, v]) => node(k, v))
    .join('')}</validation-report>`;
}
export function reportFilename(
  report: ValidationReport,
  format: 'html' | 'xml',
) {
  const sanitized = (report.file_name || '')
    .replace(/\.[^.\\/]+$/, '')
    .replace(/[\\/\p{Cc}]/gu, '')
    .replace(/[:*?"<>|]/g, '_')
    .replace(/\s+/g, ' ')
    .replace(/^[. ]+/, '')
    .trim();
  const stem = Array.from(sanitized).slice(0, 120).join('').trimEnd();
  return `${stem ? `${stem}-` : ''}validation-report.${format}`;
}
