<template>
  <q-dialog v-model="model" no-backdrop-dismiss>
    <q-card class="validation-report-panel" data-test="validation-report-panel">
      <header class="report-header">
        <h3>{{ $t('einvoice_report_title') }}</h3>
        <q-btn
          flat
          round
          dense
          icon="close"
          :aria-label="$t('einvoice_report_close')"
          data-test="report-close-icon"
          @click="model = false"
        />
      </header>
      <div v-if="view" class="report-body">
        <dl data-test="report-metadata" class="report-metadata">
          <div
            v-for="item in view.metadata"
            :key="item.key"
            :data-test="`report-${item.key}`"
          >
            <dt>{{ item.label }}</dt>
            <dd>{{ item.value }}</dd>
          </div>
        </dl>
        <div
          data-test="report-verdict"
          class="report-verdict"
          :class="view.assessment"
          role="status"
        >
          <strong
            :data-test="
              view.assessment === 'not_valid'
                ? 'status-pill-invalid'
                : 'status-pill-valid'
            "
            >{{ view.verdict }}</strong
          >
          <b data-test="report-counts">{{ view.countText }}</b>
          {{ view.organisationCountText }}
        </div>
        <section v-if="view.levels.length" data-test="report-levels">
          <h4>{{ $t('einvoice_report_levels') }}</h4>
          <table>
            <thead>
              <tr>
                <th>{{ $t('einvoice_report_levels') }}</th>
                <th>{{ $t('einvoice_report_errors') }}</th>
                <th>{{ $t('einvoice_report_warnings') }}</th>
                <th>{{ $t('einvoice_report_info') }}</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="row in view.levels"
                :key="row.key"
                :data-test="`report-level-${row.key}`"
              >
                <td>{{ row.label }}</td>
                <td>{{ row.errors }}</td>
                <td>{{ row.warnings }}</td>
                <td>{{ row.info }}</td>
              </tr>
            </tbody>
          </table>
        </section>
        <q-tabs
          v-else
          v-model="activeLayer"
          data-test="report-layer-tabs"
          align="left"
          inline-label
          dense
        >
          <q-tab
            v-for="layer in VALIDATION_LAYERS"
            :key="layer"
            :name="layer"
            :data-test="`layer-tab-${layer}`"
            :label="`${layer} · ${$t('einvoice_report_' + layer)} · ${$t('einvoice_report_counts', layerCounts(layer))}`"
          />
        </q-tabs>
        <section data-test="report-findings">
          <h4>{{ $t('einvoice_report_findings') }}</h4>
          <div class="table-scroll">
            <table class="findings-table">
              <thead>
                <tr>
                  <th>{{ $t('einvoice_report_position') }}</th>
                  <th>{{ $t('einvoice_report_code') }}</th>
                  <th>{{ $t('einvoice_report_level') }}</th>
                  <th data-test="report-organisation-column">
                    {{ $t('einvoice_report_organisation') }}
                  </th>
                  <th>{{ $t('einvoice_report_field_text') }}</th>
                </tr>
              </thead>
              <tbody>
                <tr
                  v-for="(f, index) in visibleFindings"
                  :key="index"
                  :data-test="`finding-${f.code}`"
                >
                  <td data-test="finding-position">{{ f.position }}</td>
                  <td>{{ f.code }}</td>
                  <td>
                    <span class="severity" :class="f.ruleSeverity">{{
                      $t('einvoice_report_' + f.ruleSeverity)
                    }}</span>
                  </td>
                  <td data-test="finding-organisation">
                    <span
                      v-if="f.overridden"
                      class="severity"
                      :class="f.effectiveSeverity"
                      >{{ $t('einvoice_report_' + f.effectiveSeverity) }}</span
                    ><span v-else>–</span>
                  </td>
                  <td>
                    <strong
                      v-if="f.field || f.field_name"
                      data-test="finding-field"
                      >{{ f.field }} {{ f.field_name }} · </strong
                    ><span data-test="finding-message">{{ f.message }}</span>
                    <small
                      v-if="f.technicalMessage"
                      class="technical-message"
                      data-test="finding-technical-message"
                    >
                      {{ $t('einvoice_report_technical_message') }}:
                      {{ f.technicalMessage }}
                    </small>
                    <div v-if="f.fix" data-test="finding-fix">
                      <strong>{{ $t('einvoice_report_fix') }}:</strong>
                      {{ f.fix }}
                    </div>
                    <div v-if="f.value != null" data-test="finding-value">
                      {{ $t('einvoice_report_value') }}: {{ f.value }}
                    </div>
                    <div
                      v-if="f.xpath || f.line"
                      class="finding-location"
                      data-test="finding-location"
                    >
                      <code v-if="f.xpath">{{ f.xpath }}</code>
                      <span v-if="f.line"
                        >{{ $t('einvoice_report_line') }} {{ f.line
                        }}<template v-if="f.column"
                          >:{{ f.column }}</template
                        ></span
                      >
                      <q-btn
                        v-if="f.line && f.line > 0"
                        outline
                        dense
                        no-caps
                        color="primary"
                        :label="$t('einvoice_report_show_xml')"
                        :data-test="`show-xml-${f.code}`"
                        @click="showXml(f.line)"
                      />
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
          <p
            v-if="!visibleFindings.length"
            :data-test="`empty-layer-${activeLayer}`"
          >
            {{ $t('einvoice_report_empty') }}
          </p>
        </section>
        <aside
          v-if="view.assessmentText"
          data-test="report-assessment"
          class="report-verdict"
          :class="view.assessment"
        >
          <strong>{{ $t('einvoice_report_assessment') }}:</strong>
          {{ view.assessmentText }}
        </aside>
        <section
          data-test="next-step"
          class="mt-4 border border-border rounded p-4 bg-card text-foreground"
        >
          <h4>{{ $t('einvoice_next_step') }}</h4>
          <p>
            {{
              $t(
                view.assessment === 'not_valid'
                  ? 'einvoice_next_errors'
                  : 'einvoice_next_continue',
              )
            }}
          </p>
          <footer data-test="report-actions">
            <q-btn
              v-if="canReject"
              class="f-btn"
              color="negative"
              :label="$t('einvoice_reject_document')"
              data-test="report-reject"
              @click="rejectOpen = true"
            />
            <q-btn
              color="primary"
              unelevated
              no-caps
              data-test="report-download-html"
              :label="$t('einvoice_report_html')"
              @click="download('html')"
            />
            <q-btn
              color="primary"
              outline
              no-caps
              data-test="report-download-xml"
              :label="$t('einvoice_report_xml')"
              @click="download('xml')"
            />
            <q-btn
              color="primary"
              outline
              no-caps
              data-test="report-close"
              :label="$t('einvoice_report_close')"
              @click="model = false"
            />
          </footer>
        </section>
        <EInvoiceRejectDialog
          v-if="report && canReject"
          v-model="rejectOpen"
          :report="report"
          :doc-id="docId"
          :status="documentStatus"
          :can-edit="canEdit"
          @rejected="onRejected"
        />
      </div>
    </q-card>
  </q-dialog>
</template>
<script lang="ts">
import EInvoiceRejectDialog from './EInvoiceRejectDialog.vue';
import { canRejectDocument } from 'src/utils/einvoice/rejectDocument';
import { defineComponent, type PropType } from 'vue';
import { formatReportCounts } from 'src/utils/einvoice/reportCounts';
import {
  VALIDATION_LAYERS,
  type ValidationReport,
  type ValidationLayer,
} from 'src/types/validationReport';
import {
  reportView,
  generateReportHtml,
  generateReportXml,
  reportFilename,
} from 'src/utils/einvoice/reportTemplate';
export default defineComponent({
  name: 'ValidationReportPanel',
  components: { EInvoiceRejectDialog },
  props: {
    modelValue: Boolean,
    canEdit: Boolean,
    docId: { type: String, default: '' },
    documentStatus: { type: String, default: '' },
    report: {
      type: Object as PropType<ValidationReport | null>,
      default: null,
    },
  },
  emits: ['update:modelValue', 'show-in-xml', 'rejected'],
  data: () => ({
    rejectOpen: false,
    activeLayer: 'L1' as ValidationLayer,
    VALIDATION_LAYERS,
  }),
  computed: {
    canReject(): boolean {
      return (
        Boolean(this.docId) &&
        canRejectDocument(this.canEdit, this.documentStatus)
      );
    },
    model: {
      get(): boolean {
        return this.modelValue;
      },
      set(value: boolean) {
        this.$emit('update:modelValue', value);
      },
    },
    view() {
      return this.report
        ? reportView(
            this.report,
            (key, params) => this.$t(key, params),
            (key) => this.$te(key),
            this.$i18n?.locale || 'en',
          )
        : null;
    },
    visibleFindings() {
      return (
        this.view?.findings.filter(
          (f) => this.view!.levels.length || f.layer === this.activeLayer,
        ) || []
      );
    },
  },
  watch: {
    report: {
      immediate: true,
      handler(report: ValidationReport | null) {
        this.activeLayer =
          VALIDATION_LAYERS.find((layer) =>
            report?.findings?.some((f) => f.layer === layer),
          ) || 'L1';
      },
    },
  },
  methods: {
    onRejected() {
      this.model = false;
      this.$emit('rejected');
    },
    layerCounts(layer: ValidationLayer) {
      return formatReportCounts(
        (key, params) => this.$t(key, params),
        this.$i18n?.locale || 'en',
        this.report?.summary?.[layer] || { errors: 0, warnings: 0, info: 0 },
      );
    },
    // Tolgee has no native $te: keep the finding lookup hook local and test
    // against its missing-key echo, so Wave 4 works with the live catalogue.
    $te(key: string): boolean {
      const value = this.$t(key);
      return Boolean(value && value !== key);
    },
    showXml(line: number) {
      this.model = false;
      this.$emit('show-in-xml', line);
    },
    download(format: 'html' | 'xml') {
      if (!this.report) return;
      const content =
        format === 'html'
          ? generateReportHtml(
              this.report,
              (key, params) => this.$t(key, params),
              this.$i18n?.locale || 'en',
            )
          : generateReportXml(this.report, (key, params) =>
              this.$t(key, params),
            );
      const url = URL.createObjectURL(
        new Blob([content], {
          type:
            format === 'html'
              ? 'text/html;charset=utf-8'
              : 'application/xml;charset=utf-8',
        }),
      );
      const link = document.createElement('a');
      link.href = url;
      link.download = reportFilename(this.report, format);
      link.click();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    },
  },
});
</script>
