import { CONSTANTS } from 'src/constants';
import type { Translate } from 'src/utils/translate';
import type { ValidationReport } from 'src/types/validationReport';
import { reportView } from './reportTemplate';

export function rejectionReason(
  report: ValidationReport,
  t: Translate,
  locale: string,
): string {
  return reportView(report, t, (key) => t(key) !== key, locale)
    .findings.filter((finding) => finding.effectiveSeverity === 'error')
    .sort(
      (a, b) => Number(b.severity === 'fatal') - Number(a.severity === 'fatal'),
    )
    .slice(0, 10)
    .map(
      (finding) => `${finding.code}: ${finding.message.replace(/\s+/g, ' ')}`,
    )
    .join('\n');
}

export function canRejectDocument(canEdit: boolean, status: string): boolean {
  return (
    canEdit &&
    [
      'error',
      CONSTANTS.export_error,
      CONSTANTS.ready_for_validation,
      CONSTANTS.in_review,
      'on_hold',
      CONSTANTS.validated_pending_approval,
    ].includes(status.toLowerCase())
  );
}

interface RejectApi {
  update_document_log(
    docId: string,
    reason: string,
    currentStatus: string,
    previousStatus: string,
  ): Promise<unknown>;
  set_document_status(
    docId: string,
    data: { status: string },
  ): Promise<unknown>;
}
function requireSuccess(result: unknown): void {
  if (
    !result ||
    typeof result !== 'object' ||
    !('success' in result) ||
    result.success !== true
  )
    throw result;
}
export async function rejectDocument(
  service: RejectApi,
  docId: string,
  status: string,
  reason: string,
): Promise<{ noteSaved: boolean }> {
  requireSuccess(
    await service.set_document_status(docId, { status: CONSTANTS.rejected }),
  );
  try {
    requireSuccess(
      await service.update_document_log(
        docId,
        reason,
        CONSTANTS.rejected,
        status,
      ),
    );
    return { noteSaved: true };
  } catch {
    return { noteSaved: false };
  }
}
