// Mirrors the Pydantic schema in
// doc2-api/routers/electronic_document/validation/findings.py
// — keep in sync (BOL-413).

export type ValidationLayer = 'L0' | 'L0b' | 'L0c' | 'L1' | 'L2' | 'L3' | 'L4';

export type ValidationSeverity = 'fatal' | 'error' | 'warning' | 'info';

export interface ValidationFinding {
  level?: ReportLevel | null;
  original_severity?: ValidationSeverity | null;
  position?: string | null;
  field_name?: string | null;
  layer: ValidationLayer;
  severity: ValidationSeverity;
  /** Stable, machine-readable code (BR-DE-1, XSD-CVC-COMPLEX-TYPE-4,
   *  PDFA-NOT-A3, VAL-IBAN-CHECKSUM, …). */
  code: string;
  /** BT-/BG- reference where applicable (e.g. 'BT-10'). */
  field: string | null;
  /** Exact node location in the original document. */
  xpath: string | null;
  line: number | null;
  column: number | null;
  /** Offending value (L3/L4); absent for L1/L2. */
  value: string | null;
  /** Human-readable, English. */
  message: string;
}

export interface ValidationLayerSummary {
  /** "ok" or e.g. "3 errors, 1 warning". */
  status: string;
  errors: number;
  warnings: number;
  info: number;
}

export interface ValidationReport {
  file_name?: string | null;
  checked_at?: string | null;
  seller_name?: string | null;
  invoice_number?: string | null;
  invoice_date?: string | null;
  assessment?: 'valid' | 'valid_with_warnings' | 'not_valid';
  assessment_text_key?: string;
  level_summary?: Partial<Record<ReportLevel, ValidationLayerSummary>>;
  xrechnung_type: string | null;
  syntax: 'UBL' | 'CII' | null;
  /** ZUGFeRD/Factur-X profile (MINIMUM | BASICWL | BASIC | EN16931 |
   *  EXTENDED | XRECHNUNG | DEMO). null for raw XRechnung. */
  profile: string | null;
  version: string | null;
  is_valid: boolean;
  /** Keyed by layer string ('L0', 'L0b', 'L1', …). Widened to
   *  Record<string, …> rather than Partial<Record<ValidationLayer, …>>
   *  so a future backend that emits an unknown layer key (forward-
   *  compatible serializer change) doesn't silently drop data on the
   *  TS side. The panel still looks up by ValidationLayer keys when
   *  rendering — unknown keys are ignored at render time, not at
   *  parse time. */
  summary: Record<string, ValidationLayerSummary>;
  findings: ValidationFinding[];
  bundle_version: string | null;
}

export const VALIDATION_LAYERS: readonly ValidationLayer[] = [
  'L0',
  'L0b',
  'L0c',
  'L1',
  'L2',
  'L3',
  'L4',
] as const;

