import type { Translate } from 'src/utils/translate';

/** Format count phrases for the report's plain sentence templates. */
export function formatReportCounts(
  t: Translate,
  locale: string,
  counts: { errors: number; warnings: number; info: number },
) {
  const plurals = new Intl.PluralRules(locale);
  const numbers = new Intl.NumberFormat(locale);
  const phrase = (kind: 'error' | 'warning' | 'info', count: number) =>
    t(
      `einvoice_report_count_${kind}_${plurals.select(count) === 'one' ? 'one' : 'other'}`,
      {
        count: numbers.format(count),
      },
    );
  return {
    errors: phrase('error', counts.errors),
    warnings: phrase('warning', counts.warnings),
    info: phrase('info', counts.info),
  };
}
