<template>
  <q-dialog
    :model-value="modelValue && allowed"
    persistent
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <q-card class="w-full max-w-xl bg-card text-foreground">
      <q-card-section>
        <h3 class="text-lg font-semibold">
          {{ $t('einvoice_reject_document') }}
        </h3>
        <q-input
          v-model="reason"
          type="textarea"
          outlined
          :disable="saving"
          :label="$t('einvoice_reject_reason')"
          data-test="reject-reason"
          class="my-4"
        />
        <p>{{ $t('einvoice_reject_notice') }}</p>
      </q-card-section>
      <q-card-actions align="right">
        <q-btn
          flat
          :disable="saving"
          :label="$t('einvoice_cancel')"
          @click="$emit('update:modelValue', false)"
        />
        <q-btn
          class="f-btn"
          color="negative"
          :loading="saving"
          :disable="!reason.trim() || saving"
          :label="$t('einvoice_reject_document')"
          data-test="reject-confirm"
          @click="submit"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>
<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { ValidationReport } from 'src/types/validationReport';
import DetailApiService from 'src/services/document/DetailApiService';
import {
  rejectionReason,
  canRejectDocument,
  rejectDocument,
} from 'src/utils/einvoice/rejectDocument';
import { notify } from 'src/components/notifications/notify';
const service = new DetailApiService({});
export default defineComponent({
  name: 'EInvoiceRejectDialog',
  props: {
    modelValue: Boolean,
    canEdit: Boolean,
    docId: { type: String, required: true },
    status: { type: String, required: true },
    report: { type: Object as PropType<ValidationReport>, required: true },
  },
  emits: ['update:modelValue', 'rejected'],
  data() {
    return { reason: '', saving: false, completed: false };
  },
  computed: {
    allowed(): boolean {
      return (
        Boolean(this.docId) && canRejectDocument(this.canEdit, this.status)
      );
    },
  },
  watch: {
    modelValue: {
      immediate: true,
      handler(open: boolean, wasOpen: boolean | undefined) {
        if (open && !wasOpen) {
          this.completed = false;
          this.reason = rejectionReason(
            this.report,
            (key, params) => this.$t(key, params),
            this.$i18n?.locale || 'en',
          );
        }
      },
    },
  },
  methods: {
    async submit() {
      if (!this.allowed || this.saving || this.completed || !this.reason.trim())
        return;
      this.saving = true;
      try {
        const result = await rejectDocument(
          service,
          this.docId,
          this.status,
          this.reason.trim(),
        );
        this.completed = true;
        notify.success(this.$t('einvoice_rejected'));
        if (!result.noteSaved)
          notify.warning(this.$t('einvoice_reject_note_failed'));
        this.$emit('update:modelValue', false);
        this.$emit('rejected');
      } catch {
        notify.error(this.$t('einvoice_reject_failed'));
      } finally {
        this.saving = false;
      }
    },
  },
});
</script>
